import SwiftUIstruct TimelineTaskRow: View {    let task: TaskItem    let toggle: () -> Void    let cardBackground = Color(red: 44/255, green: 44/255, blue: 46/255)    let accent = Color(red: 255/255, green: 87/255, blue: 51/255)    var body: some View {        HStack(alignment: .top, spacing: 16) {            // Línea del timeline            VStack {                Circle()                    .fill(task.isCompleted ? .green : accent)                    .frame(width: 14, height: 14)                Rectangle()                    .fill(Color.gray.opacity(0.5))                    .frame(width: 3)                    .frame(maxHeight: .infinity)            }            // Tarjeta            VStack(alignment: .leading, spacing: 6) {                HStack {                    Text(task.title)                        .font(.headline)                        .foregroundColor(.white)                    Spacer()                    Button(action: toggle) {                        Image(systemName: task.isCompleted ? "checkmark.circle.fill" : "circle")                            .foregroundColor(task.isCompleted ? .green : accent)                            .font(.title3)                    }                }                if !task.description.isEmpty {                    Text(task.description)                        .font(.subheadline)                        .foregroundColor(.white.opacity(0.8))                        .padding(.top, 2)                }                Text("Entrega: \(task.dueDate.formatted(date: .abbreviated, time: .omitted))")                    .font(.caption)                    .foregroundColor(.white.opacity(0.6))                    .padding(.top, 4)            }            .padding()            .background(cardBackground)            .cornerRadius(16)            .shadow(color: accent.opacity(0.15), radius: 6, x: 0, y: 3)            .animation(.spring(), value: task.isCompleted)        }    }}